inline constexpr const char* WAD_NAME = "SLY3.WAD";  // the game data, an ISO9660 file
inline constexpr uint32_t WAD_LBA = 0xCA0;          // ... at this sector: the keys' sectors are absolute (+0xCA0, as Sly 2)
inline constexpr uint64_t WAD_SIZE = 3492583424ull;
