// ---------------------------------------------------------------- the episodes (the values of 0x2EDF10)
enum EPISODE : int { EP_MultiPlayer, EP_Intro, EP_Trainer, EP_Venice, EP_Outback, EP_Holland, EP_China, EP_Pirate, EP_Isle, EP_Max };
inline const char* SzEpisode(int i)
{
    static const char* const s_asz[EP_Max] = {"MultiPlayer", "Intro", "Trainer", "Venice", "Outback", "Holland", "China", "Pirate", "Isle"};
    return i >= 0 && i < EP_Max ? s_asz[i] : "?";
}

